def generate_output_v7(original_grid):
    ROWS, COLS = len(original_grid), len(original_grid[0])

    # Zones: L cols 0-2, M cols 4-6, R cols 8-10
    zone_starts = [0, 4, 8]

    output = [[2 for _ in range(COLS)] for _ in range(ROWS)]

    # First pass: process bottom band (rows 7-12)
    # For each row, extract objects and their local column positions
    bottom_band_objects = {}  # row_offset (0-5) -> dict of local_col -> value
    for r in range(7, ROWS):
        row_offset = r - 7
        vals_by_local_col = {}
        for c in range(COLS):
            val = original_grid[r][c]
            if val != 2 and val != 6:
                zone_idx = (c // 4) % 3  # which zone
                local_col = c - zone_starts[zone_idx]
                if local_col not in vals_by_local_col:
                    vals_by_local_col[local_col] = set()
                vals_by_local_col[local_col].add(val)
        bottom_band_objects[row_offset] = vals_by_local_col

    # Fill bottom band
    for row_offset, vals_in_row in bottom_band_objects.items():
        actual_r = 7 + row_offset
        for zone_idx, zone_start in enumerate(zone_starts):
            for local_col, values in vals_in_row.items():
                target_col = zone_start + local_col
                if target_col < COLS:
                    for v in values:
                        output[actual_r][target_col] = v

    # Also fill top band directly (same pattern)
    for row_offset, vals_in_row in bottom_band_objects.items():
        actual_r = row_offset  # row 0-5
        for zone_idx, zone_start in enumerate(zone_starts):
            for local_col, values in vals_in_row.items():
                target_col = zone_start + local_col
                if target_col < COLS:
                    for v in values:
                        output[actual_r][target_col] = v

    return output

